use std::fs

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut first = true
    let mut width = 0
    let mut ok = false
    let mut cur = ""
    let mut cur_len = 0
    for line in text.lines() {
        if first {
            first = false
            let t = line.trim()
            match t.parse::<int>() {
                Ok(n) => {
                    if n > 0 {
                        width = n
                        ok = true
                    }
                }
                Err(_) => {}
            }
            if !ok {
                println("error: bad width")
                std::process::exit(1)
            }
        } else {
            for w in line.split_whitespace() {
                let wl: int = w.len() as int
                if cur_len == 0 {
                    cur = w
                    cur_len = wl
                } else if cur_len + 1 + wl <= width {
                    cur = "${cur} ${w}"
                    cur_len = cur_len + 1 + wl
                } else {
                    println(cur)
                    cur = w
                    cur_len = wl
                }
            }
        }
    }
    if !ok {
        println("error: bad width")
        std::process::exit(1)
    }
    if cur_len > 0 {
        println(cur)
    }
}

